import { useEffect, useRef, useState } from 'react';
import { Text, View } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { CreativeHome } from '../../src/creative/CreativeHome';
import { parseOpenCreativeRequest } from '../../src/creative/openCreativeRequest';
import { createPromptDraftStore } from '../../src/handoff/promptDraft';
import { getDatabase } from '../../src/storage/databaseClient';

export default function CreateScreen() {
  const params=useLocalSearchParams<Record<string,string|string[]>>(),router=useRouter();
  const [error,setError]=useState('');
  const prompt=Array.isArray(params.prompt)?params.prompt[0]:params.prompt;
  const converting=useRef<string|undefined>(undefined);
  useEffect(()=>{
    if(!prompt||params.draftId||converting.current===prompt)return;
    converting.current=prompt;
    void createPromptDraftStore(getDatabase()).save({prompt,attachmentIds:[]}).then(draft=>router.setParams({prompt:undefined,draftId:draft.id})).catch(()=>setError('旧提示词读取失败，请重新打开链接'));
  },[prompt,params.draftId,router]);
  return <View style={{flex:1}}>{error?<Text accessibilityRole="alert">{error}</Text>:null}<CreativeHome opening={!!prompt && !params.draftId} openRequest={parseOpenCreativeRequest(params)} onRequestConsumed={()=>router.setParams({draftId:undefined,creativeDraftId:undefined,mode:undefined,intent:undefined,requestId:undefined,prompt:undefined})}/></View>;
}

import { KeyboardSurface } from '../../src/ui/KeyboardSurface';
import { useCallback, useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Alert, FlatList, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';
import { useFocusEffect, useRouter } from 'expo-router';
import { getDatabase } from '../../src/storage/databaseClient';
import { GalleryCard } from '../../src/media/GalleryCard';
import type { MediaAsset, MediaStatus } from '../../src/media/types';
import { createSqliteMediaStore } from '../../src/media/repository';
import { extractPoster } from '../../src/native/media';
import { AppIcon } from '../../src/ui/icons';
import { ListAction, ListEmptyState, ListFilters, listUI } from '../../src/ui/ListPageUI';
import { usePageLayout, galleryColumns } from '../../src/ui/adaptiveLayout';
import { COLORS, SPACING } from '../../src/ui/theme';
import { resolveLocalVideoSource } from '../../src/tasks/localMedia';

const filters: Array<{ id: 'all' | MediaStatus; label: string }> = [{ id: 'all', label: '全部' }, { id: 'downloaded', label: '已下载' }, { id: 'downloading', label: '准备中' }, { id: 'failed', label: '失败' }];

export default function GalleryScreen() {
  const layout = usePageLayout(1200);
  const [listWidth, setListWidth] = useState(0);
  const availableWidth = listWidth || Math.max(0, Math.min(layout.width, 1200) - layout.gutter * 2);
  const columns = galleryColumns(availableWidth, layout.fontScale);
  const cardWidth = Math.max(0, (availableWidth - 13 * (columns - 1)) / columns);
  const router = useRouter();
  const [mediaStore] = useState(() => createSqliteMediaStore(getDatabase()));
  const [query, setQuery] = useState('');
  const [search, setSearch] = useState('');
  const [searchRevision, setSearchRevision] = useState(0);
  const [filter, setFilter] = useState<'all' | MediaStatus>('all');
  const [assets, setAssets] = useState<MediaAsset[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState('');
  const [pageError, setPageError] = useState('');
  const [cursor, setCursor] = useState<{ createdAt: number; id: string }>();
  const [selecting, setSelecting] = useState(false);
  const [selected, setSelected] = useState<string[]>([]);
  const [removing, setRemoving] = useState(false);
  const generation = useRef(0);
  const paging = useRef(false);
  const reading = useRef(false);
  const navigating = useRef(false);
  const posters = useRef(new Map<string, string>());
  useEffect(() => { const timer = setTimeout(() => { setSearch(query); setSearchRevision(value => value + 1); }, 300); return () => clearTimeout(timer); }, [query]);
  const enrich = useCallback(async (items: MediaAsset[], token: number) => {
    const result: MediaAsset[] = [];
    for (const source of items) {
      if (token !== generation.current) break;
      const localPath = await resolveLocalVideoSource({ task: { id: source.taskId, localUri: undefined }, asset: source });
      let asset = { ...source, localPath, posterPath: source.posterPath?.includes('/posters/sw-v3-') ? source.posterPath : undefined };
      if (source.status === 'downloaded' && !localPath) asset.status = source.sourceUrl ? 'queued' : 'failed';
      // Never rewrite the durable download state merely by searching the gallery.
      if (localPath && !asset.posterPath) {
        const key = `${asset.id}:${localPath}`;
        try {
          const poster = posters.current.get(key) ?? await extractPoster(localPath, asset.id);
          if (poster) { posters.current.set(key, poster); asset.posterPath = poster; await mediaStore.updatePoster?.(asset.id, localPath, poster); }
        } catch { /* a poster is optional; playback remains available */ }
      }
      result.push(asset);
    }
    return result;
  }, [mediaStore]);
  const load = useCallback(async () => {
    const token = ++generation.current;
    reading.current = true; paging.current = false;
    setLoading(true); setLoadingMore(false); setError(''); setPageError('');
    try {
      const options = { limit: 40, query: search, kind: 'video' as const, status: filter === 'all' ? undefined : filter };
      const page = await mediaStore.listPage?.(options) ?? { items: await mediaStore.list(options), nextCursor: undefined };
      if (token !== generation.current) return;
      setAssets(page.items); setCursor(page.nextCursor);
      const items = await enrich(page.items, token);
      if (token === generation.current) setAssets(items);
    } catch { if (token === generation.current) setError('作品读取失败，请重试'); }
    finally { if (token === generation.current) { reading.current = false; setLoading(false); } }
  }, [search, searchRevision, filter, enrich]);
  const loadMore = async () => {
    if (!cursor || paging.current || reading.current || !mediaStore.listPage) return;
    paging.current = true; setLoadingMore(true); setPageError('');
    const token = generation.current;
    try {
      const page = await mediaStore.listPage({ limit: 40, cursor, query: search, kind: 'video', status: filter === 'all' ? undefined : filter });
      const items = await enrich(page.items, token);
      if (token !== generation.current) return;
      setAssets(current => [...current, ...items.filter(item => !current.some(old => old.id === item.id))]); setCursor(page.nextCursor);
    } catch { if (token === generation.current) setPageError('加载更多失败，点击重试'); }
    finally { if (token === generation.current) { paging.current = false; setLoadingMore(false); } }
  };
  useFocusEffect(useCallback(() => { navigating.current = false; void load(); return () => { generation.current++; }; }, [load]));
  const changeQuery = (value: string) => { if (removing || value === query) return; generation.current++; setQuery(value); setSelected([]); };
  const toggle = (id: string) => { if (removing) return; setSelected(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id]); };
  const removeSelected = () => Alert.alert('删除作品', `删除 ${selected.length} 个应用内作品和私有副本，系统相册视频会保留。此操作无法撤销。`, [
    { text: '取消', style: 'cancel' }, { text: '删除', style: 'destructive', onPress: async () => {
      if (removing || !selected.length) return;
      generation.current++; setRemoving(true);
      try { for (const id of selected) await mediaStore.remove(id); setSelected([]); await load(); }
      catch { setError('部分作品未能删除，请刷新后重试'); }
      finally { setRemoving(false); }
    } },
  ]);
  const openAsset = (asset: MediaAsset) => { if (navigating.current) return; navigating.current = true; router.push({ pathname: '/video/[id]', params: { id: asset.id } }); };
  const clearFilters = () => { generation.current++; changeQuery(''); setFilter('all'); setSelected([]); setPageError(''); };
  return <KeyboardSurface style={[styles.container, layout.contentStyle]}>
    <View style={styles.selectionHeading}><Text style={styles.title}>结果</Text>{!selecting && !selected.length ? <ListAction secondary label="管理作品" onPress={() => setSelecting(true)} /> : null}</View><Text style={styles.subtitle}>浏览、播放与管理生成的作品。</Text>
    {selecting || selected.length > 0 ? <View style={styles.selectionPanel}>
      <View style={styles.selectionHeading}><Text accessibilityLiveRegion="polite" style={styles.selectionTitle}>已选择 {selected.length} 项</Text><ListAction secondary disabled={removing} label="取消选择" onPress={() => { setSelected([]); setSelecting(false); }} /></View>
      <View style={styles.selectionActions}><ListAction secondary disabled={removing || !assets.length} label="选择已加载作品" onPress={() => setSelected(assets.map(item => item.id))} /><Pressable accessibilityRole="button" accessibilityState={{ disabled: removing || !selected.length, busy: removing }} disabled={removing || !selected.length} onPress={removeSelected} style={({ pressed }) => [styles.deleteAll, pressed && listUI.pressed, (removing || !selected.length) && listUI.disabled]}><AppIcon name="delete" size={18} color={COLORS.danger} /><Text style={styles.deleteText}>{removing ? '正在删除…' : `删除 ${selected.length}`}</Text></Pressable></View>
    </View> : null}
    <View style={styles.search}><AppIcon name="search" size={21} color={COLORS.textSubtle} /><TextInput accessibilityLabel="搜索作品" value={query} onChangeText={changeQuery} placeholder="搜索 Prompt 或任务 ID..." placeholderTextColor={COLORS.textSubtle} style={styles.searchInput} />{query ? <Pressable accessibilityRole="button" accessibilityLabel="清除作品搜索" onPress={() => changeQuery('')} style={({ pressed }) => [styles.clearSearch, pressed && listUI.pressed]}><AppIcon name="close" size={18} color={COLORS.textMuted} /></Pressable> : null}</View>
    <ListFilters label="作品状态" options={filters} value={filter} onChange={value => { if (removing || value === filter) return; generation.current++; setSelected([]); setFilter(value); }} />
    {error ? <View style={listUI.notice}><Text accessibilityRole="alert" style={styles.errorText}>{error}</Text><ListAction secondary icon="refresh" label="重试读取作品列表" onPress={() => void load()} /></View> : null}
    <FlatList key={columns} onLayout={event => setListWidth(event.nativeEvent.layout.width)} data={assets} numColumns={columns} keyExtractor={item => item.id} columnWrapperStyle={columns > 1 ? styles.row : undefined} contentContainerStyle={styles.list} keyboardDismissMode="on-drag" keyboardShouldPersistTaps="handled" refreshing={loading && assets.length > 0} onRefresh={() => void load()} onEndReached={() => { if (!pageError) void loadMore(); }} onEndReachedThreshold={0.6}
      ListFooterComponent={loadingMore ? <ActivityIndicator color={COLORS.primaryActive} /> : pageError ? <ListAction secondary icon="refresh" label={pageError} onPress={() => void loadMore()} /> : assets.length && !cursor ? <Text style={listUI.footer}>已显示全部作品</Text> : null}
      renderItem={({ item }) => <GalleryCard width={cardWidth} asset={item} selected={selected.includes(item.id)} onLongPress={() => { setSelecting(true); toggle(item.id); }} onPress={() => selecting || selected.length ? toggle(item.id) : openAsset(item)} />}
      ListEmptyComponent={error ? null : <ListEmptyState icon={query || filter !== 'all' ? 'search' : 'movie_filter'} loading={loading}
        title={loading ? '正在加载作品' : query || filter !== 'all' ? '没有符合条件的作品' : '还没有视频作品'}
        description={loading ? '正在整理视频与封面，请稍候。' : query || filter !== 'all' ? '试试其他关键词，或清除筛选查看全部作品。' : '生成的视频会汇集在这里，随时浏览、播放与管理。'}
        action={loading ? undefined : query || filter !== 'all' ? { label: '清除筛选', icon: 'refresh', onPress: clearFilters } : { label: '去生成视频', icon: 'movie_filter', onPress: () => router.navigate({pathname:'/(tabs)/create',params:{mode:'video',requestId:String(Date.now())}}) }}
        secondaryAction={!loading && (query || filter !== 'all') ? { label: '去生成视频', icon: 'movie_filter', onPress: () => router.navigate({pathname:'/(tabs)/create',params:{mode:'video',requestId:String(Date.now())}}) } : undefined} />} />
  </KeyboardSurface>;
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: COLORS.background, padding: SPACING.xl },
  title: { color: COLORS.text, fontSize: 29, fontWeight: '800' },
  subtitle: { color: COLORS.textMuted, marginTop: 6, marginBottom: SPACING.lg, lineHeight: 20 },
  selectionPanel: { padding: 12, borderRadius: 16, backgroundColor: COLORS.primarySoft, borderWidth: 1, borderColor: COLORS.border, gap: 8, marginBottom: 16 },
  selectionHeading: { flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', justifyContent: 'space-between', gap: 8 },
  selectionTitle: { color: COLORS.primaryActive, fontSize: 14, fontWeight: '700' },
  selectionActions: { flexDirection: 'row', flexWrap: 'wrap', gap: 8 },
  deleteAll: { minHeight: 48, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 6, paddingHorizontal: 16, paddingVertical: 12, borderRadius: 12, backgroundColor: COLORS.dangerSoft, borderWidth: 1, borderColor: COLORS.danger },
  deleteText: { color: COLORS.danger, fontSize: 13, fontWeight: '700', lineHeight: 20 },
  errorText: { color: COLORS.danger, fontSize: 13, lineHeight: 20 },
  search: { flexDirection: 'row', alignItems: 'center', gap: 8, backgroundColor: COLORS.surface, borderRadius: 14, borderWidth: 1, borderColor: COLORS.border, paddingHorizontal: 13 },
  searchInput: { flex: 1, minWidth: 0, color: COLORS.text, minHeight: 50, fontSize: 14 },
  clearSearch: { minWidth: 48, minHeight: 48, alignItems: 'center', justifyContent: 'center' },
  list: { gap: 13, paddingBottom: 130 },
  row: { gap: 13 },
});

import { KeyboardSurface, KeyboardAwareScrollView as ScrollView } from '../../src/ui/KeyboardSurface';
import { useLocalSearchParams, useRouter, useFocusEffect } from 'expo-router';
import { CompactWorkbench,IconAction,SettingRow, TextAction } from '../../src/creative/WorkbenchUI';
import { readSettingsDraft, writeSettingsDraft } from '../../src/settings/draft';
import { DataManagementPanel } from '../../src/settings/DataManagementPanel';
import { CreativeAccountPanel } from '../../src/creative/CreativeAccountPanel';
import { videoDecodeOptions } from '../../src/settings/videoDecodeMode';
import { WorkflowSyncPanel } from '../../src/settings/WorkflowSyncPanel';
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { ActivityIndicator, Alert, BackHandler, Pressable, StyleSheet, Switch, Text, TextInput, View } from 'react-native';
import { readSettings, saveSettings } from '../../src/settings/storage';
import { DEFAULT_LLM_ADVANCED_SETTINGS as advancedDefaults } from '../../src/config/llmDefaults';
import { isDeepSeekV4, reasoningOptions } from '../../src/config/llmReasoning';
import { prepareSettingsForSave, SettingsValidationError } from '../../src/settings/validation';
import { AppIcon } from '../../src/ui/icons';
import { COLORS, SPACING } from '../../src/ui/theme';

import {useNavigation,usePreventRemove} from 'expo-router/react-navigation';
import { usePageLayout } from '../../src/ui/adaptiveLayout';
import { DisplayDiagnostics } from '../../src/settings/DisplayDiagnostics';

type Settings = Awaited<ReturnType<typeof readSettings>>;
export default function SettingsScreen({standalone=false}:{standalone?:boolean}={}) {
  const router=useRouter();
  const { section, requestId } = useLocalSearchParams<{ section?: string;requestId?:string }>();
  const navigation=useNavigation();
  const normalizeSection=(value?:string)=>value==='legacy'?'accounts':value;
  const [directEntry,setDirectEntry]=useState(standalone&&!!section);
  const [activeSection,setActiveSection]=useState(normalizeSection(section));
  useEffect(()=>{setActiveSection(normalizeSection(section));setDirectEntry(standalone&&!!section);},[section,requestId,standalone]);

  const layout = usePageLayout();
  const scrollRef = useRef<ScrollView>(null);
  useEffect(() => { scrollRef.current?.scrollTo({ y: 0, animated: false }); }, [activeSection]);
  const [values, setValues] = useState<Settings>({ ...advancedDefaults, llmEndpoint: 'https://api.openai.com/v1', llmModel: 'gpt-4o-mini', llmApiKey: '', autoExportToGallery: true, keepPrivateCopy: true });
  const [fieldErrors, setFieldErrors] = useState<Partial<Record<keyof Settings, string>>>({});
  const [saving, setSaving] = useState(false),[savedNotice,setSavedNotice]=useState('');
  const saveLock = useRef(false);
  const [pendingDraft, setPendingDraft] = useState<Partial<Settings>>();
  const [draftError, setDraftError] = useState('');
  const [draftReadError, setDraftReadError] = useState(false);
  const [baseline, setBaseline] = useState<Settings>();
  const [loadError, setLoadError] = useState(false);
  const [loadAttempt, setLoadAttempt] = useState(0);
  const dirty = baseline != null && Object.keys({ ...baseline, ...values }).some(key => values[key as keyof Settings] !== baseline[key as keyof Settings]);
  const [advancedOpen, setAdvancedOpen] = useState(false);
  useEffect(() => {
    let active = true;
    setLoadError(false); setDraftReadError(false);
    void Promise.all([readSettings(), readSettingsDraft().catch(() => { if (active) setDraftReadError(true); return undefined; })]).then(([saved, draft]) => { if (active) { const next = { ...advancedDefaults, ...saved }; setValues(next); setBaseline(next); setPendingDraft(draft); } }).catch(() => { if (active) setLoadError(true); });
    return () => { active = false; };
  }, [loadAttempt]);
  useEffect(() => {
    if (!baseline || pendingDraft || draftReadError) return;
    let active = true;
    void writeSettingsDraft(dirty ? values : undefined).then(() => { if (active) setDraftError(''); }).catch(() => { if (active) setDraftError('草稿保存失败，请保存设置后再退出'); });
    return () => { active = false; };
  }, [values, baseline, pendingDraft, dirty, draftReadError]);
  const leave=async(action:()=>void)=>{
    if(saveLock.current){setDraftError('正在保存，请稍后返回');return;}
    try{if(dirty)await writeSettingsDraft(values);action();}catch{setDraftError('草稿保存失败，当前输入仍保留，请保存设置后再返回');}
  };
  const back=()=>{
    if(activeSection&&!(directEntry)){setActiveSection(undefined);return;}
    void leave(()=>router.canGoBack()?router.back():router.navigate('/(tabs)/create'));
  };
  usePreventRemove(dirty||saving,({data})=>{void leave(()=>navigation.dispatch(data.action));});
  useFocusEffect(useCallback(()=>{const sub=BackHandler.addEventListener('hardwareBackPress',()=>{back();return true;});return()=>sub.remove();},[activeSection,directEntry,dirty,values,saving]));
  const update = (key: keyof Settings, value: string | boolean) => setValues(current => {
    const next = { ...current, [key]: value };
    if (key === 'llmModel' && !reasoningOptions(String(value)).some(option => option.value === (current.llmReasoningEffort ?? 'default'))) next.llmReasoningEffort = 'default';
    return next;
  });
  const save = async () => {
    if (saveLock.current || !baseline) return;
    saveLock.current = true; setSaving(true);
    try {
      const prepared = prepareSettingsForSave(values); setFieldErrors({});
      await saveSettings(prepared);
      setValues(current => current === values ? prepared : current); setBaseline(prepared);setSavedNotice('设置已保存，返回后生效');
    } catch (error) { if (error instanceof SettingsValidationError) { setFieldErrors(Object.fromEntries(error.fields.map(field => [field, error.message]))); setAdvancedOpen(true); setActiveSection(error.fields.some(field => field.startsWith('llm')) ? 'assistant' : 'storage'); } else Alert.alert('保存失败', error instanceof Error ? error.message : '无法保存设置'); }
    finally { saveLock.current = false; setSaving(false); }
  };
  if (!baseline) return <View style={styles.container}><TextAction label="返回来源" onPress={back}/>{loadError ? <Pressable accessibilityRole="button" accessibilityLabel="重试读取设置" onPress={() => setLoadAttempt(value => value + 1)} style={styles.saveButton}><Text style={styles.saveText}>设置读取失败，点击重试</Text></Pressable> : <ActivityIndicator accessibilityLabel="正在读取设置" />}</View>;
  return <CompactWorkbench><KeyboardSurface style={styles.container}><View style={{flexDirection:'row',alignItems:'center',paddingHorizontal:8,borderBottomWidth:0.5,borderBottomColor:COLORS.border}}><IconAction label={activeSection&&!(directEntry)?"返回设置分类":"返回来源"} icon="arrow_back" onPress={back}/><Text style={{fontSize:16,fontWeight:'600',color:COLORS.text}}>{activeSection?({accounts:'创作账号',assistant:'助手模型',workflows:'工作流',storage:'存储与导出',playback:'视频播放',advanced:'显示与诊断'} as Record<string,string>)[activeSection]:'设置'}</Text></View><ScrollView ref={scrollRef} style={styles.container} contentContainerStyle={[styles.content, layout.contentStyle]} keyboardShouldPersistTaps="handled" keyboardDismissMode="on-drag">
    {draftReadError ? <View style={styles.card}><Text accessibilityRole="alert" style={{ color: COLORS.danger }}>未保存草稿无法读取，已隔离；当前使用已保存设置。</Text><Pressable accessibilityRole="button" accessibilityLabel="丢弃无法读取的草稿" style={styles.resetAdvanced} onPress={() => { void writeSettingsDraft().then(() => { setDraftReadError(false); setDraftError(''); }).catch(() => setDraftError('无法丢弃草稿，请重试；已保存设置不受影响')); }}><Text>丢弃无法读取的草稿</Text></Pressable></View> : null}
    {pendingDraft ? <View style={styles.card}><Text>发现未保存的设置草稿</Text><Pressable accessibilityRole="button" style={styles.resetAdvanced} onPress={() => { setValues(current => ({ ...current, ...pendingDraft })); setPendingDraft(undefined); }}><Text>恢复未保存更改</Text></Pressable><Pressable accessibilityRole="button" style={styles.resetAdvanced} onPress={() => setPendingDraft(undefined)}><Text>丢弃草稿，使用已保存设置</Text></Pressable></View> : null}
    {savedNotice?<Text accessibilityLiveRegion="polite" style={{color:COLORS.textMuted}}>{savedNotice}</Text>:null}
    {draftError ? <Text accessibilityRole="alert" style={{ color: COLORS.danger }}>{draftError}</Text> : null}

    {directEntry?<TextAction label="全部设置" onPress={()=>{setDirectEntry(false);setActiveSection(undefined);}}/>:null}
    {!activeSection?<>
      <Text style={styles.groupLabel}>连接与能力</Text><View style={styles.group}>
      {([['accounts','创作账号','NovelAI · AutoDL'],['assistant','助手模型','提示词与创作辅助'],['workflows','工作流','已安装能力与同步']] as const).map(([key,label,value])=><SettingRow key={key} label={label} value={value} onPress={()=>{setDirectEntry(false);setActiveSection(key);}}/>)}
      </View><Text style={styles.groupLabel}>使用偏好</Text><View style={styles.group}>
      {([['storage','存储与导出','保存、备份与恢复'],['playback','视频播放','解码模式'],['advanced','显示与诊断','布局与运行信息']] as const).map(([key,label,value])=><SettingRow key={key} label={label} value={value} onPress={()=>setActiveSection(key)}/>)}
      </View><Text style={styles.help}>密钥加密保存在本机，账号连接与工作流配置分开管理。</Text>
    </>:null}
    {activeSection==='accounts'?<>
    <Text style={styles.help}>所有工作台共用以下连接；AutoDL 工作流使用同一份凭据。</Text>
    <CreativeAccountPanel compact />
    <CreativeAccountPanel provider="autodl" compact />

    </>:null}
    {activeSection==='assistant'?<View style={styles.card}><View style={styles.cardHeading}><AppIcon name="smart_toy" size={20} color={COLORS.primaryActive} /><Text style={styles.cardTitle}>创作助手模型</Text></View><Text style={styles.help}>用于讨论创意、编写提示词、组织镜头并协助制作。生成费用另按创作账号授权；不使用助手时可跳过。填写支持 OpenAI 兼容接口的服务地址、模型和密钥。</Text><Field label="LLM API 地址" error={fieldErrors.llmEndpoint} value={values.llmEndpoint} placeholder="https://api.openai.com/v1" autoCapitalize="none" keyboardType="url" onChangeText={(text) => update('llmEndpoint', text)} /><Field label="LLM 模型" error={fieldErrors.llmModel} value={values.llmModel} placeholder="gpt-4o-mini" autoCapitalize="none" onChangeText={(text) => update('llmModel', text)} /><Field label="LLM API Key" error={fieldErrors.llmApiKey} value={values.llmApiKey} secure placeholder="输入服务商提供的 API Key" autoCapitalize="none" onChangeText={(text) => update('llmApiKey', text)} /><Pressable accessibilityRole="button" accessibilityLabel="切换 LLM 高级设置" onPress={() => setAdvancedOpen((open) => !open)} accessibilityState={{ expanded: advancedOpen }} style={styles.advancedToggle}><Text style={styles.advancedToggleText}>高级设置</Text><AppIcon name={advancedOpen ? 'expand_less' : 'expand_more'} size={20} color={COLORS.textMuted} /></Pressable>{advancedOpen ? <View style={styles.advancedPanel}>
